# Solution code for the Cypher problem

def get_divisors(n):
    """Get all divisors of n greater than 1."""
    divs = []
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i != n // i:
                divs.append(n // i)
    if n > 1:
        divs.append(n)
    return sorted(divs)

def gcd(a, b):
    """Compute GCD of two numbers."""
    while b:
        a, b = b, a % b
    return a

def solution(input_str):
    import sys
    from io import StringIO

    input_data = StringIO(input_str)
    t_line = input_data.readline().strip()
    if not t_line:
        return ""
    t = int(t_line)

    results = []

    for _ in range(t):
        line = input_data.readline().strip()
        if not line:
            break
        n = int(line)

        divs = get_divisors(n)

        # If only one divisor, no adjacent pairs exist
        if len(divs) == 1:
            results.append(f"{divs[0]}\n0")
            continue

        # Get unique prime factors of n
        primes = set()
        temp = n
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                primes.add(d)
                temp //= d
            d += 1
        if temp > 1:
            primes.add(temp)

        # Try to arrange divisors to minimize moves
        # Group divisors by which primes divide them

        def can_satisfy(arr):
            """Check if all adjacent pairs (including wraparound) have gcd > 1"""
            k = len(arr)
            for i in range(k):
                if gcd(arr[i], arr[(i+1) % k]) == 1:
                    return False
            return True

        # Simple arrangement: try divisors in a specific order
        # Use a greedy approach: start with number containing all prime factors (if exists)

        if n in divs:
            start_idx = divs.index(n)
        else:
            start_idx = 0

        # Try various arrangements
        best_arr = None
        best_moves = float('inf')

        # Try the divisors in their natural order first
        arr = divs.copy()
        if can_satisfy(arr):
            best_arr = arr
            best_moves = 0

        # Try circular shifts
        if best_arr is None:
            for shift in range(len(divs)):
                arr = divs[shift:] + divs[:shift]
                if can_satisfy(arr):
                    best_arr = arr
                    best_moves = 0
                    break

        # If still not satisfied, we need some moves (LCM insertions)
        if best_arr is None:
            # Use the default order and count moves
            arr = divs.copy()
            best_arr = arr
            best_moves = 0  # Will calculate later if needed

            # Actually, if we can't find perfect arrangement, we need to insert LCMs
            k = len(arr)
            moves = 0
            for i in range(k):
                if gcd(arr[i], arr[(i+1) % k]) == 1:
                    moves += 1  # We need at least one LCM per coprime adjacent pair

            best_moves = min(best_moves, moves)

        if best_arr is None:
            # Fallback: use divs as arrangement
            best_arr = divs

        results.append(f"{' '.join(map(str, best_arr))}\n{best_moves}")

    return '\n'.join(results)
