                if board[nxt_idx]:
                    result.append(nxt_idx)
                    r, c = r + dr, c + dc
                else:
                    break
            else:
                break
        return result

    def rc_to_idx(r, c):
        prefix = sum(row_lengths[:r]) if r > 0 else 0
        return prefix + c

    @lru_cache(maxsize=None)
    def win(mask):
        if not mask:
            return False
        for start in mask:
