def solution(input_str):
    import sys
    from collections import defaultdict

    MOD = 10**7 + 7

    # Parse input
    lines = input_str.strip().split('\n')
    q = int(lines[0])
    queries = []
    for i in range(1, q + 1):
        parts = lines[i].split()
        queries.append((int(parts[0]), int(parts[1])))

    # Collect all n values to precompute
    max_n = 0
    for r, n in queries:
        max_n = max(max_n, n)

    # Precompute prime factorizations and number of distinct prime factors
    # For each n, we need the prime factorization to compute f0(n)
    smallest_prime = [0] * (max_n + 1)
    dist_prime_count = [0] * (max_n + 1)

    for i in range(2, max_n + 1):
        if smallest_prime[i] == 0:
            for j in range(i, max_n + 1, i):
                if smallest_prime[j] == 0:
                    smallest_prime[j] = i
                dist_prime_count[j] += 1

    # Base function f0(n) = 2^(number of distinct prime factors of n)
    def f0(n):
        if n == 1:
            return 1
        return pow(2, dist_prime_count[n], MOD)

    # Precompute divisors for each n up to max_n
    divisors = [[] for _ in range(max_n + 1)]
    for i in range(1, max_n + 1):
        for j in range(i, max_n + 1, i):
            divisors[j].append(i)

    # Recurrence: fr(n) = sum of fr(d) for proper divisors d of n, plus f0(n)
    # Actually: fr+1(n) = sum_{d|n} fr(d) where no equality to n if r+1=1
    # Standard pattern: fr(n) = sum_{d|n, d<n} fr(d) + f0(n)

    # Let's compute fr values using dynamic programming
    # For each r from 0 to max_r, compute fr(n) for all n
    max_r = 0
    for r, n in queries:
        max_r = max(max_r, r)

    # cache[r][n] stores computation result for fr(n) at level r
    cache = [[0] * (max_n + 1) for _ in range(max_r + 1)]

    # Compute f0(n) for all n
    for n in range(1, max_n + 1):
        cache[0][n] = f0(n) if n > 1 else 1

    # Now compute fr+1(n)
    for r in range(max_r):
        for n in range(1, max_n + 1):
            # fr+1(n) = sum_{d|n} fr(d)
            total = 0
            for d in divisors[n]:
                total = (total + cache[r][d]) % MOD
            if n == 1:
                cache[r + 1][n] = 1
            else:
                cache[r + 1][n] = total

    # Answer queries
    results = []
    for r, n in queries:
        results.append(str(cache[r][n]))

    return '\n'.join(results)

