def solution(input_str):
    MOD = 1000003

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = []
    for i in range(1, n + 1):
        grid.append(lines[i])

    # Convert grid to integers where '.' makes the type -1
    cells = [[-1] * m for _ in range(n)]

    # Parse the grid
    for i in range(n):
        for j in range(m):
            c = grid[i][j]
            if c != '.':
                cells[i][j] = int(c)

    def pipe_ends(pipe_type):
        """Return which directions have ends for each pipe type (1-4)"""
        ends = []
        if pipe_type == 1:  # Top + Left
            ends = {'T', 'L'}
        elif pipe_type == 2:  # Top + Right
            ends = {'T', 'R'}
        elif pipe_type == 3:  # Bottom + Left
            ends = {'B', 'L'}
        elif pipe_type == 4:  # Bottom + Right
            ends = {'B', 'R'}
        return ends

    # Check if a cell with given pipe type is valid
    def is_valid_cell(r, c, ptype, cells):
        if ptype == -1:
            return True  # Empty, we need to determine

        ends = pipe_ends(ptype)
        left_valid = True
        right_valid = True
        top_valid = True
        bottom_valid = True

        # Check left end
        if 'L' in ends:
            if c == 0:
                # Border - valid
                pass
            else:
                # Must connect to neighbor's right end
                neighbor_type = cells[r][c - 1]
                if neighbor_type == -1:
                    # Empty neighbor - constraint (will be checked during propagation)
                    pass
                else:
                    neighbor_ends = pipe_ends(neighbor_type)
                    if 'R' not in neighbor_ends:
                        left_valid = False

        # Check right end
        if 'R' in ends:
            if c == m - 1:
                # Border - valid
                pass
            else:
                neighbor_type = cells[r][c + 1]
                if neighbor_type == -1:
                    pass
                else:
                    neighbor_ends = pipe_ends(neighbor_type)
                    if 'L' not in neighbor_ends:
                        right_valid = False

        # Check top end
        if 'T' in ends:
            if r == 0:
                # Border - valid
                pass
            else:
                neighbor_type = cells[r - 1][c]
                if neighbor_type == -1:
                    pass
                else:
                    neighbor_ends = pipe_ends(neighbor_type)
                    if 'B' not in neighbor_ends:
                        top_valid = False

        # Check bottom end
        if 'B' in ends:
            if r == n - 1:
                # Border - valid
                pass
            else:
                neighbor_type = cells[r + 1][c]
                if neighbor_type == -1:
                    pass
                else:
                    neighbor_ends = pipe_ends(neighbor_type)
                    if 'T' not in neighbor_ends:
                        bottom_valid = False

        return left_valid and right_valid and top_valid and bottom_valid

    # Check pre-filled cells for validity
    for i in range(n):
        for j in range(m):
            if cells[i][j] != -1:
                if not is_valid_cell(i, j, cells[i][j], cells):
                    return "0"

    # For each cell, count valid types (validating compatibility with neighbors)
    count = 1

    for i in range(n):
        for j in range(m):
            if cells[i][j] == -1:
                # Empty cell - count valid types
                valid_types = 0

                for ptype in [1, 2, 3, 4]:
                    if is_valid_cell(i, j, ptype, cells):
                        valid_types += 1

                if valid_types == 0:
                    return "0"

                count = (count * valid_types) % MOD

    return str(count) + "\n"


