        # Calculate valid interval for x dimension
        x_start, x_end = float('-inf'), float('inf')
        if vix == 0:
            if x1 < rix < x2:
                x_start, x_end = 0.0, float('inf')
            else:
                return "-1"
        elif vix > 0:
            t1 = (x1 - rix) / float(vix)
            t2 = (x2 - rix) / float(vix)
            if t1 < t2:
                x_start, x_end = t1, t2
            else:
                return "-1"
        else:  # vix < 0
            t1 = (x2 - rix) / float(vix)
            t2 = (x1 - rix) / float(vix)
            if t1 < t2:
                x_start, x_end = t1, t2
            else:
                return "-1"

        # Calculate valid interval for y dimension
        y_start, y_end = float('-inf'), float('inf')
        if viy == 0:
            if y1 < riy < y2:
                y_start, y_end = 0.0, float('inf')
            else:
                return "-1"
        elif viy > 0:
            t1 = (y1 - riy) / float(viy)
            t2 = (y2 - riy) / float(viy)
            if t1 < t2:
                y_start, y_end = t1, t2
            else:
