    MOD = 10**9 + 7

    def concat(a, b):
        """Concatenate number a with number b using modular arithmetic."""
        b_len = len(str(b))
        return (a * pow(10, b_len, MOD) + b) % MOD

    def parse(expr, idx):
        n = len(expr)
        pos = idx

        def parse_number():
            start = pos
            while pos < n and expr[pos].isdigit():
                pos += 1
            if start != pos:
                result = int(expr[start:pos])
                return result, pos
            return 0, pos

        def parse_term():
            nonlocal pos
            l, pos = parse_number()
            if pos >= n:
                return l, pos

            if expr[pos] == '-':
                pos += 1
                r, _ = parse_number()
                # Concatenate l, l+1, ..., r with modular arithmetic
                result = l
                current_len = len(str(l))
                for i in range(l + 1, r + 1):
                    val_str = str(i)
                    val_len = len(val_str)
                    result = concat(result, i)
                    current_len += val_len
                return result, pos

            elif expr[pos] == '(':
                pos += 1  # skip '('
                inner_expr, inner_pos = parse(expr, pos)
                if pos < n and expr[pos] == ')':
                    pos += 1  # skip ')'
                repeat_times = l
                inner_val = inner_expr if isinstance(inner_expr, int) else 0

                result = 0
                for _ in range(repeat_times):
                    if repeat_times > 1:
                        result = (result * pow(10, len(str(inner_val)), MOD) + inner_val) % MOD
                    else:
                        result = inner_val % MOD
                return result, pos

            else:
                return l, pos

        pos = idx
        left, _ = parse_term()

        while pos < n and expr[pos] == '+':
            pos += 1  # skip '+'
            right, _ = parse_term()
            left = concat(left, right)

        return left

    result = parse(expr, 0)
    return str(result)
